
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_camy_pbeh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_camy_pbeh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.195348844044033e-01, -3.186246596815618e-01, -3.173515412085359e-01, -3.155972768363557e-01, -3.132401129683243e-01, -3.102146773578237e-01, -3.066800783322995e-01, -3.034237898795105e-01, -3.024255991717453e-01, -3.043247718888927e-01, -2.867343363000950e-01, -2.464154947142399e-01, -2.357687575249865e-01, -2.176585156222903e-01, -1.913176566393439e-01, -1.544105201172276e-01, -1.000837472269501e-01, -3.932898017623222e-02, -8.646728945278513e-03, -9.729577923563170e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


